(()=>{const $=id=>document.getElementById(id);let state;const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e};async function api(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers},cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}const message=text=>$('message').textContent=text;async function load(){try{state=await api('/api/admin/state');$('health').replaceChildren();for(const [name,s]of Object.entries(state.sources||{}))$('health').append(el('div',name+': '+(s.ok?'Connected · '+(s.count??0)+' findings':s.error||'Unavailable')));$('health').append(el('div','X token: '+(state.xConnected?'saved securely':'not connected')));$('health').append(el('div','X daily request budget: '+(state.xBudget?.day===new Date().toISOString().slice(0,10)?state.xBudget.reservedReads:0)+' / 50 posts reserved. Broader filtering adds no requests.'));$('pendingCount').textContent=(state.pending||[]).length+' pending';$('candidates').replaceChildren();for(const item of state.pending||[]){const card=el('article',null,'review-card'),h=el('h3',item.title),source=el('a','Open original source ↗');source.href=item.url;source.target='_blank';source.rel='noopener noreferrer';card.append(h,el('p',item.source+' · '+item.status,'status'),source);const form=el('form'),inputs={};for(const [key,title]of [['title','Headline'],['summary','What happened'],['effect','What it changes'],['next','What to watch']]){const label=el('label',title),input=el(key==='title'?'input':'textarea');input.value=item[key]||'';input.required=true;input.maxLength=key==='title'?180:1400;label.append(input);form.append(label);inputs[key]=input}const label=el('label','Affects'),select=el('select');select.multiple=true;select.size=4;for(const v of ['Supply','Revenue','Price','Buybacks']){const o=el('option',v);o.value=v;o.selected=(item.affects||[]).includes(v);select.append(o)}label.append(select);form.append(label);const details=el('details'),sum=el('summary','Source evidence');details.append(sum,el('pre',JSON.stringify(item.evidence||{text:item.summary},null,2)));const actions=el('div',null,'admin-actions'),publish=el('button','Publish'),dismiss=el('button','Dismiss');publish.type='submit';dismiss.type='button';dismiss.onclick=async()=>{try{await api('/api/admin/review',{method:'POST',body:JSON.stringify({id:item.id,action:'dismiss'})});await load()}catch(e){message(e.message)}};actions.append(publish,dismiss);form.append(details,actions);form.onsubmit=async e=>{e.preventDefault();publish.disabled=true;try{await api('/api/admin/review',{method:'POST',body:JSON.stringify({id:item.id,action:'publish',...Object.fromEntries(Object.entries(inputs).map(([k,v])=>[k,v.value])),affects:[...select.selectedOptions].map(o=>o.value)})});message('Published.');await load()}catch(err){message(err.message)}finally{publish.disabled=false}};card.append(form);$('candidates').append(card)}if(!state.pending?.length)$('candidates').append(el('p','No findings waiting for review.','status'))}catch(e){message(e.message)}}$('nearblocksForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;message('Saving and testing NearBlocks…');try{const d=await api('/api/admin/nearblocks',{method:'POST',body:JSON.stringify({token:$('nearblocksKey').value})});message(d.status?.ok?'NearBlocks key saved securely. Connection test passed.':'Key saved; connection test: '+(d.status?.httpStatus||d.status?.error||'unavailable'))}catch(err){message(err.message)}finally{$('nearblocksKey').value='';b.disabled=false}};$('xForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;message('Saving and testing X…');try{const d=await api('/api/admin/x',{method:'POST',body:JSON.stringify({token:$('xToken').value})});message(d.status?.ok?'X connected. New posts are in the review queue.':'Token saved; X test: '+(d.status?.error||'unavailable'));await load()}catch(err){message(err.message)}finally{$('xToken').value='';button.disabled=false}};$('disconnectX').onclick=async()=>{try{await api('/api/admin/x',{method:'DELETE'});message('X disconnected.');await load()}catch(e){message(e.message)}};$('refreshSources').onclick=async()=>{$('refreshSources').disabled=true;message('Collecting source updates…');try{await api('/api/catalysts/sync',{method:'POST',body:'{}'});message('Collection complete.');await load()}catch(e){message(e.message)}finally{$('refreshSources').disabled=false}};$('reloadState').onclick=load;load()})();
